static rt_err_t bf0_audio_configure(struct rt_audio_device *audio, struct rt_audio_caps *caps)
{
    rt_err_t result = RT_EOK;
    struct bf0_audio_codec *audcodec = (struct bf0_audio_codec *) audio;
    AUDCODEC_HandleTypeDef *haudcodec = (AUDCODEC_HandleTypeDef *) & (audcodec->audcodec);

    if (audio == NULL || caps == NULL)
        return RT_ERROR;

    switch (caps->main_type)
    {
    case AUDIO_TYPE_INPUT:
    {
        uint8_t i;
        const AUDCODE_ADC_CLK_CONFIG_TYPE *adc_clk = &codec_adc_clk_config_xtal[0];
        if (use_pll_all)
        {
            adc_clk = &codec_adc_clk_config_pll[0];
        }
        for (i = 0; i < 9; i++)
        {
            if (caps->udata.config.samplerate == adc_clk[i].samplerate)
            {
                haudcodec->Init.samplerate_index = i;
                haudcodec->Init.adc_cfg.adc_clk = (AUDCODE_ADC_CLK_CONFIG_TYPE *)&adc_clk[i];
                break;
            }
        }

        if (caps->sub_type & (1 << (HAL_AUDCODEC_ADC_CH0)))
        {
#ifdef BSP_AUDCODEC_ADC0_DMA
            if (haudcodec->buf[HAL_AUDCODEC_ADC_CH0] == NULL)
            {
                haudcodec->buf[HAL_AUDCODEC_ADC_CH0] = calloc_dma_friendly_sram(1, haudcodec->bufSize);
                if (haudcodec->buf[HAL_AUDCODEC_ADC_CH0] == NULL)
                    return RT_ERROR_MEMFAULT;
            }
#endif
            audcodec->rx_instanc = HAL_AUDCODEC_ADC_CH0;
        }

        if (caps->sub_type & (1 << (HAL_AUDCODEC_ADC_CH1)))
        {
#ifdef BSP_AUDCODEC_ADC1_DMA
            if (haudcodec->buf[HAL_AUDCODEC_ADC_CH1] == NULL)
            {
                haudcodec->buf[HAL_AUDCODEC_ADC_CH1] = calloc_dma_friendly_sram(1, haudcodec->bufSize);
                if (haudcodec->buf[HAL_AUDCODEC_ADC_CH1] == NULL)
                    return RT_ERROR_MEMFAULT;
            }
#endif
            audcodec->rx_instanc = HAL_AUDCODEC_ADC_CH1;
        }

    }
    break;
    case AUDIO_TYPE_OUTPUT:
    {
        uint8_t i;
        const AUDCODE_DAC_CLK_CONFIG_TYPE *dac_clk = &codec_dac_clk_config_xtal[0];
        if (use_pll_all)
        {
            dac_clk = &codec_dac_clk_config_pll[0];
        }
        for (i = 0; i < 9; i++)
        {
            if (caps->udata.config.samplerate == dac_clk[i].samplerate)
